const BY_ID = new Map(FRAMEWORKS.map((f) => [f.id, f]));
const BY_LABEL = new Map(FRAMEWORKS.map((f) => [f.label, f]));

export function getFramework(id: string): FrameworkDef | undefined {
  return BY_ID.get(id);
}

export function getFrameworkByLabel(label: string): FrameworkDef | undefined {
  return BY_LABEL.get(label);
}

/** Control-framework picker source: control-kind frameworks that have content. */
export function getControlFrameworks(opts: { populatedOnly?: boolean } = {}): FrameworkDef[] {
  return FRAMEWORKS.filter(
    (f) => f.entityKind === 'control' && (!opts.populatedOnly || f.populated),
  );
}

